arguments.command:
curl -s -X POST https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: Bearer <TOKEN>' -d '{"query":"{ __schema { mutationType { fields { name args { name type { name kind ofType { name kind } } } type { name } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['mutationType']['fields']:
    if 'issue' in f['name'].lower():
        print(f['name'], '->', f['type']['name'])
        for a in f['args']:
            t=a['type']; tn=t.get('name') or (t.get('ofType') or {}).get('name')
            print('   arg:', a['name'], tn, t['kind'])
"

